import type { RawWorkbookData } from './workbook-mapping';

/**
 * Generated by `npm run data:import`. The file is git-ignored, so a fresh clone
 * falls back to sanitised demo data instead of shipping live operations data.
 */
const modules = import.meta.glob('./generated-dashboard.json', { eager: true }) as Record<
  string,
  { default: RawWorkbookData }
>;

const embedded = Object.values(modules)[0]?.default ?? null;

export const embeddedWorkbookData: RawWorkbookData | null = embedded;
